-- OPS-TOOL-SHAPE-FM-1 (2026-11-05, session C-ops-tools; charter pillar autonomy; program QNFO.OPS). The failure mode behind LOOP-BREAKER / TOOL-FAILURE tickets 1000838, 1000990, 1001245, 1001394, 1001460, 1001469:
-- a model calls an ops tool with the wrong argument shape (the call envelope sent as the arguments, a renamed or missing argument, an invented op, a PCRE flag in a JavaScript regex, a worker name that is not
-- deployed), the tool answers with an error and logs it as status error, and the loop breaker files a ticket per signature. OPS-ARG-ALIAS-1 (qnfo-ops 2.62.20) and OPS-TOOL-ERRSHAPE-1 (2.66.1) fix the shapes seen
-- so far; this registers the detector that reads the next one: an ops_ai_tool event with status error whose error text is one of the caller-shape signatures, counted from the moment 2.66.1 or later reached
-- production (fleet_deploys), expected 0. A miss files through the failure-mode path (escalate_to qnfo-fleet-control), whose hourly tick routes it to the code loop. No gate, no owner card.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM remediation_contracts WHERE class = 'fm-ops-tool-shape'; DELETE FROM failure_modes WHERE fm_key = 'ops-tool-shape';
-- CAUSE-MAPPED: registers no metric_registry row; the detector is a failure_modes row with a remediation contract.

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('ops-tool-shape', 'an ops tool answers a caller-input mistake (wrong argument shape) as a tool failure, and the loop breaker files a ticket for every signature',
  'models send the function-call envelope as the arguments, rename an argument, invent an op, write PCRE flags into a JavaScript regex or name a worker that is not deployed; the tool returned a plain error that logToolEvent recorded as status error, and a long argument cut the event meta mid-JSON so even the error text was unreadable',
  'qnfo-ops unwraps the envelope, accepts the aliases, coerces an invented op, reads (?i) as a flag, answers a missing node or worker as a lookup miss (not_found, logged ok) and a bad argument as arg_error (logged rejected), and fits the event meta into one valid JSON object; tests in qnfo-ops/tool-arg-alias.test.mjs and tool-errshape.test.mjs',
  'the fm-ops-tool-shape contract counts ops_ai_tool events with status error whose error text is a caller-shape signature since qnfo-ops 2.66.1 reached production, expected 0',
  'fm-ops-tool-shape', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), NULL,
  'an ops_ai_tool cloud_ops_events row with status error and an error text such as "required", "op must be one of", "invalid regex", "Invalid group" or "not a deployed worker"',
  'the same LOOP-BREAKER-1 or TOOL-FAILURE ticket reopens within 24 hours for a tool argument',
  'ops tool loops: the agent retries the same wrong call and files tickets instead of answering');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-ops-tool-shape', NULL, 'OPS-TOOL-SHAPE-FM-1', 'failure-mode detector',
  'WITH d AS (SELECT MIN(ts) AS t FROM fleet_deploys WHERE worker = ''qnfo-ops'' AND ok = 1 AND to_sha GLOB ''2.[0-9]*.[0-9]*'' AND CAST(substr(to_sha, 3, instr(substr(to_sha, 3), ''.'') - 1) AS INTEGER) * 1000 + CAST(substr(to_sha, 3 + instr(substr(to_sha, 3), ''.'')) AS INTEGER) >= 66001) SELECT ''0'' AS expected, CASE WHEN d.t IS NULL THEN ''fix not deployed yet'' ELSE CAST((SELECT COUNT(*) FROM cloud_ops_events e WHERE e.kind = ''ops_ai_tool'' AND e.status = ''error'' AND e.ts > d.t AND e.ts > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-24 hours'') AND (instr(e.meta, '' required'') > 0 OR instr(e.meta, ''op must be one of'') > 0 OR instr(e.meta, ''invalid regex'') > 0 OR instr(e.meta, ''Invalid group'') > 0 OR instr(e.meta, ''not a deployed worker'') > 0 OR instr(e.meta, ''is not a function'') > 0)) AS TEXT) END AS observed FROM d',
  'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode', datetime('now'));

